Javascript.Source:
var content = context.getVariable("response.event.current.content");
var eventText = "";
var finishReason = "";
if (content) {
    var dataPrefixIdx = content.indexOf("data: ");
    if (dataPrefixIdx !== -1) {
        var jsonStr = content.substring(dataPrefixIdx + 6).trim();
        try {
            var parsed = JSON.parse(jsonStr);
            if (parsed.candidates && parsed.candidates.length > 0) {
                var candidate = parsed.candidates[0];
                finishReason = candidate.finishReason || "";
                if (candidate.content && candidate.content.parts && candidate.content.parts.length > 0) {
                    for (var p = 0; p < candidate.content.parts.length; p++) {
                        if (candidate.content.parts[p].text) {
                            eventText += candidate.content.parts[p].text;
                        }
                    }
                }
            }
        } catch (e) {}
    }
}

var previousBuf = context.getVariable("tmp_buffer_pre") || "";
var totalBuf = previousBuf + eventText;

if (totalBuf.length > 0) {
    context.setVariable("response_partial", totalBuf);
    context.setVariable("buff_ready", "true");
    context.setVariable("tmp_buffer_pre", totalBuf);
} else {
    context.setVariable("buff_ready", "false");
    context.setVariable("response_partial", "");
    context.setVariable("tmp_buffer_pre", "");
}
